def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    bg = max(set(x for row in g for x in row), key=lambda x: sum(row.count(x) for row in g))

    # Find a full, uniform row or column acting as the boundary.
    boundary = None
    for r in range(h):
        if len(set(g[r])) == 1 and g[r][0] != bg:
            boundary = ("h", r, g[r][0])
            break
    if boundary is None:
        for c in range(w):
            vals = [g[r][c] for r in range(h)]
            if len(set(vals)) == 1 and vals[0] != bg:
                boundary = ("v", c, vals[0])
                break
    if boundary is None:
        return g

    axis, pos, line_color = boundary
    points = [(r, c) for r in range(h) for c in range(w)
              if g[r][c] != bg and g[r][c] != line_color]
    if not points:
        return g

    if axis == "h":
        lo = min(r for r, c in points)
        hi = max(r for r, c in points)
        shift = (pos + 1) - lo if pos < lo else (pos - 1) - hi
        moved = [(r + shift, c, g[r][c]) for r, c in points]
        for r, c in points:
            g[r][c] = bg
        for r, c, color in moved:
            g[r][c] = color
        trailing = max(r for r, c, _ in moved) + 1 if pos < lo else min(r for r, c, _ in moved) - 1
        if 0 <= trailing < h:
            g[trailing] = [8] * w
    else:
        lo = min(c for r, c in points)
        hi = max(c for r, c in points)
        shift = (pos + 1) - lo if pos < lo else (pos - 1) - hi
        moved = [(r, c + shift, g[r][c]) for r, c in points]
        for r, c in points:
            g[r][c] = bg
        for r, c, color in moved:
            g[r][c] = color
        trailing = max(c for r, c, _ in moved) + 1 if pos < lo else min(c for r, c, _ in moved) - 1
        if 0 <= trailing < w:
            for r in range(h):
                g[r][trailing] = 8

    return g
